+import static org.junit.jupiter.api.Assertions.assertDoesNotThrow;
+import static org.junit.jupiter.api.Assertions.assertEquals;
+
+/**
+ * UC-002: View Veterinarians.
+ */
+class UC002ViewVeterinariansTest extends PetClinicTestBase {
+
+    @Autowired
+    private DSLContext dsl;
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = "BR-003")
+    void visitorReachesVeterinariansWithoutAuthentication() {
+        assertDoesNotThrow(() -> navigate(VetsView.class),
+                "Expected the 'vets' route to resolve to VetsView without logging in");
+    }
+
+    @Test
+    @UseCase(id = "UC-002")
+    void veterinariansGridIsRendered() {
+        navigate(VetsView.class);
+
+        assertDoesNotThrow(() -> find(H2.class).withText("Veterinarians").single(),
+                "Expected the Veterinarians heading");
+        assertDoesNotThrow(() -> find(Grid.class).single(),
+                "Expected exactly one veterinarians grid");
+    }
+
+    @Test
+    @UseCase(id = "UC-002")
+    void gridListsEveryVeterinarianInNameOrder() {
+        Grid<Vet> grid = openVeterinariansGrid();
+
+        assertEquals(6, count(grid), "Expected all six seeded veterinarians");
+        List<Vet> vets = fetch(grid, 0, 6);
+        assertEquals("James", vets.get(0).firstName());
+        assertEquals("Carter", vets.get(0).lastName());
+        assertEquals("Sharon", vets.get(2).firstName());
+        assertEquals("Stevens", vets.get(5).lastName());
+    }
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = "BR-001")
+    void gridFetchesOnlyTheRequestedWindow() {
+        Grid<Vet> grid = openVeterinariansGrid();
+
+        List<Vet> window = fetch(grid, 2, 2);
+
+        assertEquals(List.of("Sharon Jenkins", "Helen Leary"),
+                window.stream().map(vet -> vet.firstName() + " " + vet.lastName()).toList(),
+                "Expected the second window of the directory, not the whole table");
+    }
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = "BR-002")
+    void specialtiesAreListedAlphabetically() {
+        Grid<Vet> grid = openVeterinariansGrid();
+
+        Vet douglas = fetch(grid, 1, 1).get(0);
+
+        assertEquals(List.of("dentistry", "surgery"), douglas.specialties());
+        assertEquals("dentistry, surgery", VetsView.specialtiesText(douglas));
+    }
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = "BR-002")
+    void vetWithoutSpecialtiesShowsNone() {
+        Grid<Vet> grid = openVeterinariansGrid();
+
+        Vet carter = fetch(grid, 0, 1).get(0);
+
+        assertEquals(VetsView.NO_SPECIALTIES, VetsView.specialtiesText(carter));
+    }
+
+    @Test
+    @UseCase(id = "UC-002", scenario = "A1: No Veterinarians Registered")
+    void emptyDirectoryRendersGridWithNoRows() {
+        dsl.deleteFrom(VET_SPECIALTIES).execute();
+        dsl.deleteFrom(VETS).execute();
+
+        Grid<Vet> grid = openVeterinariansGrid();
+
+        assertEquals(0, count(grid), "Expected an empty veterinarians grid");
