+
+    /** Reads a window of rows the way the grid does when it scrolls. */
+    private static List<Vet> fetch(Grid<Vet> grid, int offset, int limit) {
+        return provider(grid).fetch(new Query<>(offset, limit, List.of(), null, null)).toList();
+    }
+
+    /** Asks the count callback how many rows the grid would scroll through. */
+    private static int count(Grid<Vet> grid) {
